// src/runtime.ts
class PluginRuntime {
  clientName;
  tools = new LearningTools;
  secrets = new Secrets;
  auth;
  constructor(clientName) {
    this.clientName = clientName;
  }
  async call(name, input = {}) {
    try {
      this.tools.validateInput(name, input);
      if (!this.auth) {
        const base = resolveBase();
        this.auth = new Auth(base, new CredentialStore(base, this.clientName(), this.secrets), this.secrets);
      }
      return this.secrets.clean(await this.tools.call(this.auth, name, input));
    } catch (error) {
      return this.secrets.clean(safeError(error));
    }
  }
  async waitForSignIn() {
    await this.auth?.waitForIdle();
  }
  async stop() {
    await this.auth?.cancel();
  }
}

